<script setup lang="ts">
import QueryCompare from '../components/QueryCompare.vue';
import {sqlReport} from '../report';
import {ref,computed,watch} from 'vue';import {useLab} from '../store';import {type Execution,type Trace,type Table,type Analysis,exportText} from '../api';import SqlEditor from '../components/SqlEditor.vue';import ResultTable from '../components/ResultTable.vue';import TraceView from '../components/TraceView.vue';import SchemaExplorer from '../components/SchemaExplorer.vue';import GraphView from '../components/GraphView.vue';
const props=defineProps<{theme:string}>();const lab=useLab();const editor=ref<InstanceType<typeof SqlEditor>>();const output=ref<Execution>();const trace=ref<Trace>();const plan=ref<Table>();const analysis=ref<Analysis>({diagnostics:[],ast:[],statements:[]});const tab=ref('result');const resultIndex=ref(0);const stale=ref(false);const width=ref(46);const lastSql=ref('');const activeResult=computed(()=>output.value?.results[resultIndex.value]);watch(()=>lab.epoch,()=>{stale.value=true;trace.value=undefined;plan.value=undefined});
watch(()=>[lab.workspace?.active_document,lab.engine],()=>{lab.invalidateJobs(['sql','trace','plan','compare']);trace.value=undefined;plan.value=undefined});
async function run(all=false){if(lab.jobs.trace)await lab.cancel('trace');trace.value=undefined;const sql=await editor.value?.source(all);if(!sql)return;lastSql.value=sql;const r=await lab.run<Execution>('sql','execute',{sql});if(!r)return;trace.value=undefined;plan.value=undefined;output.value=r;resultIndex.value=Math.max(0,r.results.length-1);tab.value='result';stale.value=false;lab.log(r.error??`完成 ${r.results.length} 个结果 · ${r.elapsed_ms} ms · ${r.transaction}`);if(r.error)lab.error=r.error;if(r.modified)lab.markDirty();await lab.refresh();}
async function visualize(){trace.value=undefined;const sql=await editor.value?.source();if(!sql)return;lastSql.value=sql;const r=await lab.run<Trace>('trace','trace',{sql});if(r){trace.value=r;tab.value='flow';stale.value=false;lab.log(r.message)}}
async function explain(){const sql=await editor.value?.source();if(!sql)return;const r=await lab.run<Table|Execution>('plan','explain',{sql});if(r){plan.value='results'in r?r.results[0]?.table:r;tab.value='plan';stale.value=false;}}
function edit(text:string){if(lab.active){lab.active.text=text;lab.touch();}}
function add(){const id=crypto.randomUUID();lab.workspace!.documents.push({id,title:`查询-${lab.workspace!.documents.length+1}.sql`,text:'SELECT * FROM Student;'});lab.workspace!.active_document=id;lab.touch();}
function resize(e:PointerEvent){const start=e.clientX;const previous=width.value;const container=(e.target as HTMLElement).parentElement!;function move(ev:PointerEvent){width.value=Math.max(28,Math.min(65,previous+(ev.clientX-start)/container.clientWidth*100))}function stop(){window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop)}window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop);}
const schemaNodes=computed(()=>lab.schema.relations.map(r=>({id:r.name,label:r.name,detail:r.columns.map(c=>c.primary_key?`◆ ${c.name}`:c.name).join(' · ')})));const schemaEdges=computed(()=>lab.schema.relations.flatMap(r=>r.foreign_keys.map(f=>({source:r.name,target:f.target,label:f.columns.join(',')}))));
async function report(){const content=sqlReport(lastSql.value,lab.schema.engine,output.value,trace.value);await exportText(content,'SQL 实验报告.md');}
</script>
<template><div class="ide-page"><SchemaExplorer @insert="editor?.insertReference($event.relation,$event.column)"/><div class="ide-work"><div class="editor-pane" :style="{width:`${width}%`}"><div class="file-tabs"><button v-for="doc in lab.workspace?.documents" :key="doc.id" :class="{active:doc.id===lab.workspace?.active_document}" @click="lab.workspace!.active_document=doc.id"><span class="sql-tag">SQL</span>{{doc.title}}</button><button @click="add" title="新建 SQL 标签">＋</button></div><div class="editor-toolbar"><button class="primary" data-testid="run" :disabled="!!lab.jobs.sql" @click="run(false)">▶ 运行</button><button @click="run(true)" :disabled="!!lab.jobs.sql">运行脚本</button><button @click="editor?.format()">格式化</button><button class="subtle" @click="lab.cancel()" :disabled="!Object.keys(lab.jobs).length">■ 取消</button></div><SqlEditor v-if="lab.active" ref="editor" :id="lab.active.id" :model-value="lab.active.text" :schema="lab.schema" :engine="lab.engine" :theme="props.theme" @update:model-value="edit" @run="run(false)" @script="run(true)" @diagnostics="analysis=$event"/><div class="editor-hint"><span>Ctrl+Enter 当前语句 · Ctrl+Alt+Enter 脚本</span><span>Ctrl+Space 补全</span></div><details class="problems" :open="analysis.diagnostics.some(d=>d.severity==='error')"><summary>问题 <span class="badge">{{analysis.diagnostics.length}}</span></summary><p v-for="(d,i) in analysis.diagnostics" :key="i" :class="d.severity">{{d.range.line}}:{{d.range.column}} · {{d.message}}</p></details></div><div class="resize-handle" @pointerdown="resize"/><div class="output-pane"><div class="panel-tabs"><button v-for="item in [['result','结果'],['flow','查询过程'],['schema','结构'],['plan','执行计划'],['compare','SQL 对照']]" :key="item[0]" :class="{active:tab===item[0]}" @click="tab=item[0]">{{item[1]}}</button></div><div class="output-toolbar"><button data-testid="trace" :disabled="!!lab.jobs.trace" @click="visualize">◇ 生成查询过程</button><button @click="explain">EXPLAIN</button><button :disabled="!output&&!trace" @click="report().catch(lab.fail)">报告 ↗</button><span v-if="stale&&(output||trace)" class="stale">输入已变更</span></div><div class="output-scroll"><QueryCompare v-if="tab==='compare'" :theme="props.theme"/><template v-else-if="tab==='result'"><div v-if="output" class="execution-meta"><span :class="output.status==='completed'?'success':'error'">{{output.status==='completed'?'✓ 执行完成':output.status}}</span><span>{{output.elapsed_ms}} ms</span><span>{{output.transaction}}</span><select v-if="output.results.length>1" v-model="resultIndex"><option v-for="(r,i) in output.results" :key="i" :value="i">结果 {{i+1}} · {{r.affected}} 行受影响</option></select></div><div v-if="output?.error" class="notice warning">{{output.error}}</div><ResultTable v-if="activeResult" :table="activeResult.table" :title="activeResult.table.columns.length?'查询结果':`${activeResult.affected} 行受影响`"/><div v-else class="welcome"><div class="welcome-symbol">SQL</div><h2>写一条查询，看懂每一步。</h2><p>从左侧选择表，或直接运行课堂示例。<br>切换「查询过程」，查看数据如何流向结果。</p><div class="welcome-chips"><span>真实 SQLite</span><span>离线可用</span><span>逐步解释</span></div></div></template><TraceView v-else-if="tab==='flow'&&trace" :trace="trace" @highlight="editor?.highlight($event)"/><div v-else-if="tab==='flow'" class="empty">点击「生成查询过程」开始。逻辑步骤与原生执行计划分别展示。</div><template v-else-if="tab==='schema'"><GraphView :nodes="schemaNodes" :edges="schemaEdges"/><details v-for="r in lab.schema.relations" :key="r.name" class="definition"><summary>{{r.name}} · {{r.columns.length}} 列</summary><pre>{{r.definition}}</pre></details></template><ResultTable v-else-if="tab==='plan'&&plan" :table="plan" title="数据库原生执行计划"/><div v-else class="empty">点击 EXPLAIN 查看数据库报告的执行计划。</div></div></div></div></div></template>
